SELECT id, signal_id, execution_key, symbol, side, quantity, price_usdt, decision_price_usdt, execution_price_observed_at, gross_amount_usdt, fee_usdt, cost_basis_usdt, realized_pnl_usdt, execution_type, execution_reason, status, executed_at, LEFT(execution_message, 700) AS execution_message FROM crypto_ai.wallet_trade WHERE id IN (344,346,357,358,359,392,401,403,407,426,429,451,454) ORDER BY executed_at;